function deepClone(obj){ return JSON.parse(JSON.stringify(obj)); }
function getAdminSettings(){
    try{
        const raw=localStorage.getItem(ADMIN_SETTINGS_KEY);
        if(!raw) return deepClone(DEFAULT_ADMIN_SETTINGS);
        const saved=JSON.parse(raw);
        const d=deepClone(DEFAULT_ADMIN_SETTINGS);
        const out=Object.assign(d,saved||{});
        out.packageNames=Object.assign({},d.packageNames,saved.packageNames||{});
        out.labels=Object.assign({},d.labels,saved.labels||{});
        out.packages=Object.assign({},d.packages,saved.packages||{});
        out.weddingPackages=Object.assign({},d.weddingPackages,saved.weddingPackages||{});
        out.novitiationPackages=Object.assign({},d.novitiationPackages,saved.novitiationPackages||{});
        out.features=Object.assign({},d.features,saved.features||{});
        out.customLabels=Array.isArray(saved.customLabels)?saved.customLabels:d.customLabels;
        out.mainPackageOptions=Array.isArray(saved.mainPackageOptions)?saved.mainPackageOptions:d.mainPackageOptions;
        out.paymentOptions=Array.isArray(saved.paymentOptions)&&saved.paymentOptions.length?saved.paymentOptions:d.paymentOptions;
        out.statusOptions=Array.isArray(saved.statusOptions)&&saved.statusOptions.length?saved.statusOptions:d.statusOptions;
        return out;
    }catch(e){ return deepClone(DEFAULT_ADMIN_SETTINGS); }
}
function saveAdminSettingsObject(settings){
    try{
        localStorage.setItem(ADMIN_SETTINGS_KEY,JSON.stringify(settings));
        return true;
    }catch(e){
        console.error("Admin settings save error:",e);
        alert("Settings သိမ်းမရပါ။ Logo အရွယ်အစားကို လျှော့ပြီး ပြန်စမ်းပါ။");
        return false;
    }
}
function money(value){
    return Number(value||0).toLocaleString() + " " + getAdminSettings().currency;
}
function L(key, fallback){
    const st=getAdminSettings();
    return (st.labels && st.labels[key]) || fallback || key;
}
function specialPackageName(type){
    const st=getAdminSettings();
    if(type==='wedding') return (st.packageNames && st.packageNames.wedding) || DEFAULT_ADMIN_SETTINGS.packageNames.wedding;
    if(type==='novitiation') return (st.packageNames && st.packageNames.novitiation) || DEFAULT_ADMIN_SETTINGS.packageNames.novitiation;
    return (st.packageNames && st.packageNames.custom) || DEFAULT_ADMIN_SETTINGS.packageNames.custom;
}
function isWeddingPackage(name){
    return name===specialPackageName('wedding') || name===DEFAULT_ADMIN_SETTINGS.packageNames.wedding;
}
function isNovitiationPackage(name){
    return name===specialPackageName('novitiation') || name===DEFAULT_ADMIN_SETTINGS.packageNames.novitiation;
}
function isCustomPackage(name){
    return name===specialPackageName('custom') || name===DEFAULT_ADMIN_SETTINGS.packageNames.custom;
}
function isFeatureEnabled(key){
    const st=getAdminSettings();
    return !st.features || st.features[key] !== false;
}
function customMainPackageByName(name){
    const st=getAdminSettings();
    return (st.mainPackageOptions||[]).find(function(x){ return String(x.name)===String(name); }) || null;
}
function applyFeatureToggles(){
    const st=getAdminSettings();
    const map={
        dashboard:['dashboardSection'], calendar:['calendarSection'], voucherForm:['voucherFormSection'],
        voucherPreview:['voucherPreviewSection'], voucherList:['voucherListSection','voucherListButton'], search:['search','searchButton'],
        backup:['backupButton'], restore:['restoreButton'], shareImage:['shareImageButton'], navigation:['backButton','homeButton'],
        currentPackagePrices:['dashboardPackagePricesContent'], customer:['customerLabel','customer'], phone:['phoneLabel','phone'],
        location:['locationLabel','location'], package:['packageLabel','package','packageSubOptionsBox'], weddingMainPackage:['weddingPackageLabel','weddingPackage','weddingPackageBox'],
        novitiationMainPackage:['novitiationPackageLabel','NovitiationPackage','NovitiationPackageBox'],
        customMainPackage:[], shootDate:['shootDateLabel','shootDate'], shootTime:['shootTimeLabel','shootTime'],
        status:['statusLabel','status'], amount:['amountLabel','amount'], discount:['discountLabel','discount'],
        deposit:['depositLabel','deposit'], paymentStatus:['paymentStatusLabel','paymentStatus'], note:['noteLabel','note']
    };
    Object.keys(map).forEach(function(key){
        const show=isFeatureEnabled(key);
        map[key].forEach(function(id){ const el=document.getElementById(id); if(el) el.style.display=show?'':'none'; });
    });
    const priceContent=document.getElementById('dashboardPackagePricesContent');
    if(priceContent && !isFeatureEnabled('currentPackagePrices')) priceContent.style.display='none';

    // Wedding / Novitiation are sub-options of the Main Package function.
    // If Package is OFF, both sub-package selectors stay hidden regardless of their own switch.
    const packageEnabled=isFeatureEnabled('package');
    const weddingBox=document.getElementById('weddingPackageBox');
    const novitiationBox=document.getElementById('NovitiationPackageBox');
    if(weddingBox) weddingBox.style.display=(packageEnabled && isFeatureEnabled('weddingMainPackage'))?'block':'none';
    if(novitiationBox) novitiationBox.style.display='none';
    if(weddingBox) weddingBox.style.display='none';
    if(packageEnabled) syncIntegratedPackageOption();
    else {
        const subBox=document.getElementById('packageSubOptionsBox');
        if(subBox) subBox.style.display='none';
    }
}
function applyCustomLabels(){
    const st=getAdminSettings();
    (st.customLabels||[]).forEach(function(item){
        if(item.enabled===false || !item.target) return;
        try{ document.querySelectorAll(item.target).forEach(function(el){
            if(item.mode==='placeholder') el.placeholder=item.text||'';
            else el.textContent=item.text||'';
        }); }catch(e){ console.warn('Custom label target error',item.target); }
    });
}
function applyInterfaceLabels(){
    const map={
        adminButton:'adminButton', adminTitle:'adminTitle', dashboardTitle:'dashboardTitle', calendarTitle:'calendarTitle', previous:'previousButton', next:'nextButton',
        newVoucherTitle:'newVoucherTitle', customer:'customerLabel', phone:'phoneLabel', location:'locationLabel', package:'packageLabel',
        weddingPackage:'weddingPackageLabel', novitiationPackage:'novitiationPackageLabel', shootDate:'shootDateLabel', shootTime:'shootTimeLabel',
        status:'statusLabel', amount:'amountLabel', discount:'discountLabel', deposit:'depositLabel', paymentStatus:'paymentStatusLabel', note:'noteLabel',
        createVoucher:'createVoucherButton', shareImage:'shareImageButton', voucherListButton:'voucherListButton', searchButton:'searchButton',
        backup:'backupButton', restore:'restoreButton', voucherPreviewTitle:'voucherPreviewTitle', voucherListTitle:'voucherListTitle',
        back:'backButton', home:'homeButton', removeLogo:'removeLogoButton', addPayment:'addPaymentButton', addStatus:'addStatusButton', saveSettings:'saveSettingsButton', resetSettings:'resetSettingsButton', deleteAll:'deleteAllButton', closeAdmin:'closeAdminButton'
    };
    Object.keys(map).forEach(function(k){ const el=document.getElementById(map[k]); if(el) el.textContent=L(k,el.textContent); });
    const search=document.getElementById('search'); if(search) search.placeholder=L('searchPlaceholder',search.placeholder);
    const packageSelect=document.getElementById('package'); if(packageSelect){ const first=packageSelect.querySelector('option[value=""]'); if(first) first.textContent=L('packagePlaceholder',first.textContent); }
    const weddingSelect=document.getElementById('weddingPackage'); if(weddingSelect){ const first=weddingSelect.querySelector('option[value=""]'); if(first) first.textContent=L('subPackagePlaceholder',first.textContent); }
    const novSelect=document.getElementById('NovitiationPackage'); if(novSelect){ const first=novSelect.querySelector('option[value=""]'); if(first) first.textContent=L('subPackagePlaceholder',first.textContent); }
    const priceToggle=document.querySelector('.dashboard-price-toggle'); if(priceToggle) priceToggle.textContent=L('currentPackagePrices',priceToggle.textContent);
    const appName=document.getElementById('applicationNameText'); if(appName) appName.textContent=getAdminSettings().applicationName;
    applyCustomLabels();
    applyFeatureToggles();
}

