function addCustomLabelOption(){
    const st=getAdminSettings();
    st.customLabels=Array.isArray(st.customLabels)?st.customLabels:[];
    const name=window.prompt('Label Name ထည့်ပါ','New Label'); if(name===null) return;
    const clean=String(name).trim(); if(!clean){alert('Label Name မရှိပါ');return;}
    const target=window.prompt('Target ID / CSS Selector ထည့်ပါ','#customerLabel'); if(target===null) return;
    const text=window.prompt('Label Text ထည့်ပါ',clean); if(text===null) return;
    st.customLabels.push({name:clean,target:String(target).trim(),text:String(text),mode:'text',enabled:true});
    saveAdminSettingsObject(st); applyInterfaceLabels(); renderAdminEditor();
}
function removeCustomLabelOption(index){
    const st=getAdminSettings(); if(!Array.isArray(st.customLabels)) return;
    if(!confirm('ဒီ Custom Label ကိုဖျက်မှာ သေချာပါသလား?')) return;
    st.customLabels.splice(index,1); saveAdminSettingsObject(st); applyInterfaceLabels(); renderAdminEditor();
}
function addMainPackageOption(){
    const st=getAdminSettings(); st.mainPackageOptions=Array.isArray(st.mainPackageOptions)?st.mainPackageOptions:[];
    const name=window.prompt('Main Package Name ထည့်ပါ','New Main Package'); if(name===null) return;
    const clean=String(name).trim(); if(!clean){alert('Package Name မရှိပါ');return;}
    const reserved=[specialPackageName('wedding'),specialPackageName('novitiation'),specialPackageName('custom')].map(String);
    if(reserved.includes(clean) || Object.keys(st.packages).includes(clean) || st.mainPackageOptions.some(x=>String(x.name)===clean)){ alert('ဒီ Main Package Name ရှိပြီးသားပါ'); return; }
    const priceText=window.prompt('Main Package Price (MMK) ထည့်ပါ','0'); if(priceText===null) return;
    st.mainPackageOptions.push({name:clean,price:Math.max(0,Number(String(priceText).replace(/,/g,''))||0),enabled:true});
    saveAdminSettingsObject(st); applyInterfaceLabels(); renderAdminEditor(); showDashboard();
}
function removeMainPackageOption(index){
    const st=getAdminSettings(); if(!Array.isArray(st.mainPackageOptions)) return;
    if(!confirm('ဒီ Main Package Option ကိုဖျက်မှာ သေချာပါသလား?')) return;
    st.mainPackageOptions.splice(index,1); saveAdminSettingsObject(st); applyInterfaceLabels(); renderAdminEditor(); showDashboard();
}

function applyAdminSettings(){
    const st=getAdminSettings();
    document.documentElement.style.setProperty("--mz-bg",st.backgroundColor);
    document.documentElement.style.setProperty("--mz-primary",st.primaryColor);
    document.documentElement.style.setProperty("--mz-dark",st.darkColor);

    // Update every Business Name / Subtitle element, including the
    // dedicated Voucher Preview panel.
    document.querySelectorAll(".business-name").forEach(el=>el.textContent=st.businessName);
    document.querySelectorAll(".business-subtitle").forEach(el=>el.textContent=st.subtitle);
    document.title=st.applicationName || (st.businessName + " Voucher System");
    applyInterfaceLabels();

    const hasCustomLogo=!!(st.logoData && String(st.logoData).trim());
    // Default interface logo is a clean white/transparent version.
    // A selected custom logo is always shown in its original colors.
    const interfaceLogo=hasCustomLogo ? st.logoData : "logo_interface_default_white.png";
    const voucherLogo=hasCustomLogo ? st.logoData : "logo_interface_default_white.png";
    document.querySelectorAll(".logo").forEach(el=>{
        el.src=interfaceLogo;
        el.style.display="block";
        el.style.filter="none";
    });
    document.querySelectorAll(".voucherLogo").forEach(el=>{
        el.src=voucherLogo;
        el.style.display="block";
        el.style.filter="none";
    });

    // Keep the main form's package prices synchronized with Admin settings.
    syncPackagePricesToForm();
    renderAdminSelectOptions();
    applyInterfaceLabels();
    applyFeatureToggles();
}

function getPackagePrice(packageName, subPackageName){
    const st=getAdminSettings();
    if(isWeddingPackage(packageName)){
        return Number(st.weddingPackages[subPackageName] || 0);
    }
    if(isNovitiationPackage(packageName)){
        return Number(st.novitiationPackages[subPackageName] || 0);
    }
    const customMain=customMainPackageByName(packageName);
    if(customMain) return Number(customMain.price||0);
    return Number(st.packages[packageName] || 0);
}

function syncPackagePricesToForm(){
    const st=getAdminSettings();
    const packageSelect=document.getElementById("package");
    const weddingSelect=document.getElementById("weddingPackage");
    const novSelect=document.getElementById("NovitiationPackage");

    if(packageSelect){
        const oldValue=packageSelect.value;
        let html='<option value="">'+escapeHtml(L('packagePlaceholder','-- Package ရွေးပါ --'))+'</option>';
        Object.keys(st.packages).forEach(name=>{
            html += '<option value="'+escapeHtml(name)+'">'+escapeHtml(name)+'</option>';
        });
        (st.mainPackageOptions||[]).forEach(function(item){
            if(item.enabled===false) return;
            html += '<option value="'+escapeHtml(item.name)+'">'+escapeHtml(item.name)+'</option>';
        });
        if(isFeatureEnabled('weddingMainPackage')) html += '<option value="'+escapeHtml(specialPackageName('wedding'))+'">'+escapeHtml(specialPackageName('wedding'))+'</option>';
        if(isFeatureEnabled('novitiationMainPackage')) html += '<option value="'+escapeHtml(specialPackageName('novitiation'))+'">'+escapeHtml(specialPackageName('novitiation'))+'</option>';
        if(isFeatureEnabled('customMainPackage')) html += '<option value="'+escapeHtml(specialPackageName('custom'))+'">'+escapeHtml(specialPackageName('custom'))+'</option>';
        packageSelect.innerHTML=html;
        if(Array.from(packageSelect.options).some(opt=>opt.value===oldValue)) packageSelect.value=oldValue;
    }
    if(weddingSelect){
        let html='<option value="">'+escapeHtml(L('subPackagePlaceholder','Package ရွေးပါ'))+'</option>';
        Object.entries(st.weddingPackages).forEach(([name,price])=>{
            html+='<option value="'+escapeHtml(name)+'">'+escapeHtml(name)+(price>0?' - '+escapeHtml(money(price)):'')+'</option>';
        });
        const old=weddingSelect.value; weddingSelect.innerHTML=html;
        if(Array.from(weddingSelect.options).some(opt=>opt.value===old)) weddingSelect.value=old;
    }
    if(novSelect){
        let html='<option value="">'+escapeHtml(L('subPackagePlaceholder','Package ရွေးပါ'))+'</option>';
        Object.entries(st.novitiationPackages).forEach(([name,price])=>{
            html+='<option value="'+escapeHtml(name)+'">'+escapeHtml(name)+(price>0?' - '+escapeHtml(money(price)):'')+'</option>';
        });
        const old=novSelect.value; novSelect.innerHTML=html;
        if(Array.from(novSelect.options).some(opt=>opt.value===old)) novSelect.value=old;
    }
    syncIntegratedPackageOption();
}

