function collectAdminSettings(saveNow=true){
    const st=getAdminSettings();
    const val=id=>{const e=document.getElementById(id); return e?e.value.trim():"";};
    st.applicationName=val("adminApplicationName")||DEFAULT_ADMIN_SETTINGS.applicationName;
    st.businessName=val("adminBusinessName")||DEFAULT_ADMIN_SETTINGS.businessName;
    st.subtitle=val("adminSubtitle")||DEFAULT_ADMIN_SETTINGS.subtitle;
    st.labels=Object.assign({},DEFAULT_ADMIN_SETTINGS.labels,st.labels||{});
    document.querySelectorAll('[data-admin-label]').forEach(function(el){ if(el.value.trim()) st.labels[el.getAttribute('data-admin-label')]=el.value.trim(); });
    st.features=Object.assign({},DEFAULT_ADMIN_SETTINGS.features,st.features||{});
    document.querySelectorAll('[data-admin-feature]').forEach(function(el){ st.features[el.getAttribute('data-admin-feature')]=!!el.checked; });
    st.customLabels=Array.from(document.querySelectorAll('[data-custom-label-name]')).map(function(el){
        const i=el.getAttribute('data-custom-label-name');
        const target=document.querySelector('[data-custom-label-target="'+i+'"]');
        const text=document.querySelector('[data-custom-label-text="'+i+'"]');
        const mode=document.querySelector('[data-custom-label-mode="'+i+'"]');
        const enabled=document.querySelector('[data-custom-label-enabled="'+i+'"]');
        return {name:el.value.trim(),target:target?target.value.trim():'',text:text?text.value:'',mode:mode?mode.value:'text',enabled:enabled?!!enabled.checked:true};
    }).filter(function(x){return x.name && x.target;});
    st.mainPackageOptions=Array.from(document.querySelectorAll('[data-main-package-name]')).map(function(el){
        const i=el.getAttribute('data-main-package-name');
        const price=document.querySelector('[data-main-package-price="'+i+'"]');
        const enabled=document.querySelector('[data-main-package-enabled="'+i+'"]');
        return {name:el.value.trim(),price:Math.max(0,Number(price?price.value:0)||0),enabled:enabled?!!enabled.checked:true};
    }).filter(function(x){return x.name;});
    st.packageNames=Object.assign({},DEFAULT_ADMIN_SETTINGS.packageNames,st.packageNames||{});
    document.querySelectorAll('[data-admin-special-package]').forEach(function(el){ var v=el.value.trim(); if(v) st.packageNames[el.getAttribute('data-admin-special-package')]=v; });
    st.voucherPrefix=val("adminVoucherPrefix");
    st.currency=val("adminCurrency")||DEFAULT_ADMIN_SETTINGS.currency;
    st.backgroundColor=val("adminBgColor")||DEFAULT_ADMIN_SETTINGS.backgroundColor;
    st.primaryColor=val("adminPrimaryColor")||DEFAULT_ADMIN_SETTINGS.primaryColor;
    st.darkColor=val("adminDarkColor")||DEFAULT_ADMIN_SETTINGS.darkColor;
    const rebuildPackageGroup=function(group){
        const obj=group==='package'?st.packages:(group==='wedding'?st.weddingPackages:st.novitiationPackages);
        const rows=Array.from(document.querySelectorAll('[data-admin-package-name="'+group+'"]'));
        const oldObj=Object.assign({},obj); const next={};
        rows.forEach(function(nameEl){
            const oldKey=nameEl.getAttribute('data-old-key'); const newKey=nameEl.value.trim();
            const priceEl=Array.from(document.querySelectorAll('[data-admin-price="'+group+'"]')).find(function(el){ return el.getAttribute('data-key')===oldKey; });
            const price=priceEl?Math.max(0,Number(priceEl.value)||0):Number(oldObj[oldKey]||0);
            if(newKey && !Object.prototype.hasOwnProperty.call(next,newKey)) next[newKey]=price;
        });
        if(Object.keys(next).length) { Object.keys(obj).forEach(function(k){delete obj[k];}); Object.assign(obj,next); }
    };
    rebuildPackageGroup('package'); rebuildPackageGroup('wedding'); rebuildPackageGroup('novitiation');
    const readOptions=type=>Array.from(document.querySelectorAll('[data-admin-option="'+type+'"]')).map(e=>e.value.trim()).filter(Boolean);
    const pays=readOptions('payment'), statuses=readOptions('status');
    if(pays.length) st.paymentOptions=pays;
    if(statuses.length) st.statusOptions=statuses;
    const pin=val("adminPin"); if(pin) st.adminPin=pin;
    if(saveNow) {
        saveAdminSettingsObject(st);
        applyAdminSettings();
        showDashboard(); showVouchers(); refreshCalendar();
        if(currentVoucher) displayVoucher(currentVoucher);
        alert("Admin Settings သိမ်းပြီးပါပြီ");
    }
    return st;
}
function saveAdminSettings(){
    const file=document.getElementById("adminLogoFile");
    const finishSave=(logoData)=>{
        const st=collectAdminSettings(false);
        if(logoData !== undefined) st.logoData=logoData;
        if(!saveAdminSettingsObject(st)) return;
        applyAdminSettings();
        renderAdminEditor();
        applyInterfaceLabels();
        showDashboard();
        showVouchers();
        refreshCalendar();
        if(currentVoucher) displayVoucher(currentVoucher);
        alert("Admin Settings သိမ်းပြီးပါပြီ");
    };

    if(file && file.files && file.files[0]){
        const selected=file.files[0];
        if(!selected.type || !selected.type.startsWith("image/")){
            alert("Logo အတွက် Image File ကိုသာရွေးပါ");
            return;
        }
        compressAdminLogo(selected).then(dataUrl=>finishSave(dataUrl)).catch(err=>{
            console.error(err);
            alert("Logo ပြောင်းမရပါ။ အခြား Image File တစ်ခုနဲ့ ပြန်စမ်းပါ။");
        });
    }else{
        finishSave(undefined);
    }
}
function compressAdminLogo(file){
    return new Promise((resolve,reject)=>{
        const reader=new FileReader();
        reader.onerror=()=>reject(reader.error || new Error("File read failed"));
        reader.onload=()=>{
            const img=new Image();
            img.onerror=()=>reject(new Error("Image decode failed"));
            img.onload=()=>{
                const maxSide=800;
                const scale=Math.min(1,maxSide/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));
                const canvas=document.createElement("canvas");
                canvas.width=Math.max(1,Math.round((img.naturalWidth||img.width)*scale));
                canvas.height=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));
                const ctx=canvas.getContext("2d");
                if(!ctx) return reject(new Error("Canvas unavailable"));
                ctx.clearRect(0,0,canvas.width,canvas.height);
                ctx.drawImage(img,0,0,canvas.width,canvas.height);

                // PNG keeps transparent MZ logos intact while resizing them enough
                // to stay safely within localStorage limits on Android WebView/iPhone.
                let data=canvas.toDataURL("image/png");
                // If still unusually large, use WebP quality as a safe fallback.
                if(data.length>500000){
                    const webp=canvas.toDataURL("image/webp",0.82);
                    if(webp && webp.length < data.length) data=webp;
                }
                resolve(data);
            };
            img.src=reader.result;
        };
        reader.readAsDataURL(file);
    });
}

