function syncIntegratedPackageOption(){
    const pack=(document.getElementById("package")||{}).value || "";
    const box=document.getElementById("packageSubOptionsBox");
    const label=document.getElementById("packageSubLabel");
    const select=document.getElementById("packageSubOption");
    if(!box || !label || !select) return;

    const oldWedding=document.getElementById("weddingPackageBox");
    const oldNov=document.getElementById("NovitiationPackageBox");
    if(oldWedding) oldWedding.style.display="none";
    if(oldNov) oldNov.style.display="none";

    let group="";
    if(isWeddingPackage(pack) && isFeatureEnabled('weddingMainPackage')) group="wedding";
    else if(isNovitiationPackage(pack) && isFeatureEnabled('novitiationMainPackage')) group="novitiation";

    if(!group){
        box.style.display="none";
        select.innerHTML='<option value="">'+escapeHtml(L('subPackagePlaceholder','Package ရွေးပါ'))+'</option>';
        select.value="";
        return;
    }

    const st=getAdminSettings();
    const source=group==='wedding'?st.weddingPackages:st.novitiationPackages;
    const previous=select.value;
    label.textContent=group==='wedding' ? L('weddingPackage','Wedding Package') : L('novitiationPackage','Novitiation Package');
    let html='<option value="">'+escapeHtml(L('subPackagePlaceholder','Package ရွေးပါ'))+'</option>';
    Object.entries(source).forEach(function(entry){
        const name=entry[0], price=entry[1];
        html+='<option value="'+escapeHtml(name)+'">'+escapeHtml(name)+(price>0?' - '+escapeHtml(money(price)):'')+'</option>';
    });
    select.innerHTML=html;
    if(Array.from(select.options).some(function(o){return o.value===previous;})) select.value=previous;
    box.style.display="block";
    if(select.value) setIntegratedPackagePrice();
}

function setIntegratedPackagePrice(){
    const pack=(document.getElementById("package")||{}).value || "";
    const sub=(document.getElementById("packageSubOption")||{}).value || "";
    const amount=document.getElementById("amount");
    if(!amount) return;
    if(isWeddingPackage(pack)) amount.value=getPackagePrice(specialPackageName('wedding'),sub) || "";
    else if(isNovitiationPackage(pack)) amount.value=getPackagePrice(specialPackageName('novitiation'),sub) || "";
}

function setPackagePrice(){
    const pack=(document.getElementById("package")||{}).value || "";
    const amount=document.getElementById("amount");
    if(!amount) return;
    const integrated=document.getElementById("packageSubOption");
    if(integrated) integrated.value="";
    const oldWedding=document.getElementById("weddingPackage");
    const oldNov=document.getElementById("NovitiationPackage");
    if(oldWedding) oldWedding.value="";
    if(oldNov) oldNov.value="";

    if(isWeddingPackage(pack) || isNovitiationPackage(pack)){
        amount.value="";
        syncIntegratedPackageOption();
        return;
    }
    syncIntegratedPackageOption();
    amount.value = isCustomPackage(pack) ? "" : (getPackagePrice(pack,"") || "");
}

function setWeddingPrice(){
    const value=(document.getElementById("packageSubOption")||{}).value || (document.getElementById("weddingPackage")||{}).value || "";
    const amount=document.getElementById("amount");
    if(amount) amount.value=getPackagePrice(specialPackageName('wedding'),value) || "";
}

function setNovitiationPrice(){
    const value=(document.getElementById("packageSubOption")||{}).value || (document.getElementById("NovitiationPackage")||{}).value || "";
    const amount=document.getElementById("amount");
    if(amount) amount.value=getPackagePrice(specialPackageName('novitiation'),value) || "";
}

let editingIndex = -1;
let currentVoucher = null;

function getVouchers(){
    try {
        let raw = localStorage.getItem("vouchers");
        if (!raw) raw = localStorage.getItem("MZ_VOUCHERS");
        if (!raw) return [];
        const data = JSON.parse(raw);
        return Array.isArray(data) ? data : [];
    } catch(e) {
        console.error("Voucher data read error:", e);
        return [];
    }
}

function saveVouchers(data){
    const json = JSON.stringify(Array.isArray(data) ? data : []);
    localStorage.setItem("vouchers", json);
    localStorage.setItem("MZ_VOUCHERS", json);
}

// ===============================
// Booking Calendar
// ===============================
let calendarDate = new Date();
calendarDate.setDate(1);

function pad2(n){ return String(n).padStart(2, "0"); }
function getLocalDateKey(date){
    return date.getFullYear() + "-" + pad2(date.getMonth()+1) + "-" + pad2(date.getDate());
}
function escapeHtml(value){
    return String(value ?? "").replace(/[&<>\"]/g, function(ch){
        return ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"})[ch];
    });
}

function changeMonth(offset){
    calendarDate.setMonth(calendarDate.getMonth() + Number(offset || 0));
    renderCalendar();
}

function renderCalendar(){
    const calendar = document.getElementById("calendar");
    const title = document.getElementById("monthTitle");
    const bookingList = document.getElementById("bookingList");
    if (!calendar || !title) return;

    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    title.textContent = monthNames[month] + " " + year;

    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const vouchers = getVouchers();
    const bookings = {};

    vouchers.forEach(function(v){
        const key = String(v.shootDate || "").trim();
        if (!key) return;
        if (!bookings[key]) bookings[key] = [];
        bookings[key].push(v);
    });

    let html = '<table class="calendar"><thead><tr>';
    ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].forEach(function(day){ html += '<th>' + day + '</th>'; });
    html += '</tr></thead><tbody><tr>';

    for(let i=0; i<firstDay; i++) html += '<td class="empty-day"></td>';

    for(let day=1; day<=daysInMonth; day++){
        const date = new Date(year, month, day);
        const key = getLocalDateKey(date);
        const dayBookings = bookings[key] || [];
        const bookedClass = dayBookings.length ? ' booked' : '';
        const count = dayBookings.length ? '<span class="booking-count">📸 ' + dayBookings.length + '</span>' : '';
        html += '<td class="calendar-day' + bookedClass + '" data-date="' + key + '" onclick="showBookingsForDate(\'' + key + '\')">' + day + count + '</td>';
        if(date.getDay() === 6 && day !== daysInMonth) html += '</tr><tr>';
    }

    const lastDay = new Date(year, month, daysInMonth).getDay();
    for(let i=lastDay+1; i<7; i++) html += '<td class="empty-day"></td>';
    html += '</tr></tbody></table>';
    calendar.innerHTML = html;

    if(bookingList && !bookingList.dataset.selected){
        bookingList.innerHTML = '<div class="calendar-hint">📸 Booked dates are highlighted. Tap a date to view bookings.</div>';
    }
}

function showBookingsForDate(dateKey){
    const bookingList = document.getElementById("bookingList");
    if(!bookingList) return;
    const vouchers = getVouchers().filter(function(v){ return String(v.shootDate || "").trim().slice(0,10) === dateKey; });
    bookingList.dataset.selected = dateKey;

    if(!vouchers.length){
        bookingList.innerHTML = '<div class="calendar-hint">No booking on ' + escapeHtml(dateKey) + '.</div>';
        return;
    }

    let html = '<div class="booking-date-title">📅 ' + escapeHtml(dateKey) + '</div>';
    vouchers.forEach(function(v){
        html += '<div class="booking-item">' +
            '<b>' + escapeHtml(v.number) + '</b><br>' +
            escapeHtml(L('calendarCustomer','Customer')) + ' : ' + escapeHtml(v.customer) + '<br>' +
            escapeHtml(L('calendarPackage','Package')) + ' : ' + escapeHtml(v.package) + '<br>' +
            escapeHtml(L('calendarTime','Time')) + ' : ' + escapeHtml(v.shootTime || "-") + '<br>' +
            '<button type="button" onclick="showVoucherByNumber(\'' + String(v.number).replace(/'/g, "\\'") + '\')">' + escapeHtml(L('viewVoucher','View Voucher')) + '</button>' +
            '</div>';
    });
    bookingList.innerHTML = html;
}

function refreshCalendar(){
    const list = document.getElementById("bookingList");
    if(list) list.removeAttribute("data-selected");
    renderCalendar();
}

function createVoucher(){

let customer=document.getElementById("customer").value.trim();
let phone=document.getElementById("phone").value.trim();
let location=document.getElementById("location").value.trim();

let basePackage=document.getElementById("package").value;
let integratedPack=(document.getElementById("packageSubOption")||{}).value || "";
let weddingPack=isWeddingPackage(basePackage) ? integratedPack : "";
let novitiationPack=isNovitiationPackage(basePackage) ? integratedPack : "";
let originalPackage=basePackage;

if(isWeddingPackage(basePackage) && weddingPack){
    originalPackage += " - " + weddingPack;
}
if(isNovitiationPackage(basePackage) && novitiationPack){
    originalPackage += " - " + novitiationPack;
}

let status=document.getElementById("status").value;
let amount=document.getElementById("amount").value;
let discount=document.getElementById("discount").value || 0;
let deposit=document.getElementById("deposit").value || 0;
let paymentStatus=document.getElementById("paymentStatus").value;
let note=document.getElementById("note").value.trim();
let shootDate=document.getElementById("shootDate").value;
let shootTime=document.getElementById("shootTime").value;

if(!customer || !phone || !location){
    alert("အချက်အလက် ဖြည့်ပါ");
    return;
}
if(isWeddingPackage(basePackage) && !weddingPack){
    alert("Wedding Package ရွေးပါ");
    return;
}
if(isNovitiationPackage(basePackage) && !novitiationPack){
    alert("Novitiation Package ရွေးပါ");
    return;
}
if(amount==="" || Number(amount)<0){
    alert("Amount မှန်ကန်စွာ ထည့်ပါ");
    return;
}

let amountNum=Number(amount);
let discountNum=Math.max(0,Number(discount)||0);
let depositNum=Math.max(0,Number(deposit)||0);
let balance=amountNum-discountNum-depositNum;
if(balance<0){
    alert("Discount + Deposit က Amount ထက် မများရပါ");
    return;
}

let vouchers=getVouchers();

if(editingIndex>=0 && vouchers[editingIndex]){
    // UPDATE: keep the original voucher number/date instead of deleting the record.
    let old=vouchers[editingIndex];
    let updated={
        number:old.number,
        customer, phone, location,
        package:originalPackage,
        status,
        amount:amountNum,
        discount:discountNum,
        deposit:depositNum,
        balance,
        paymentStatus,
        note,
        shootDate,
        shootTime,
        date:old.date || new Date().toLocaleString(),
        updatedDate:new Date().toLocaleString()
    };
    vouchers[editingIndex]=updated;
    saveVouchers(vouchers);
    editingIndex=-1;
    setCreateButtonMode(false);
    clearForm();
    showDashboard();
    showVouchers();
    refreshCalendar();
    displayVoucher(updated);
    alert("Voucher ပြင်ဆင်ပြီးပါပြီ");
    return;
}

// NEW VOUCHER: calculate the next number from the highest existing number,
// so deleting a voucher never causes a duplicate voucher number.
let maxNo=0;
vouchers.forEach(v=>{
    let m=String(v.number||"").match(/(\d+)$/);
    if(m) maxNo=Math.max(maxNo,parseInt(m[1],10)||0);
});
let voucherNumber=getAdminSettings().voucherPrefix+String(maxNo+1).padStart(6,"0");

let voucher={
    number:voucherNumber,
    customer, phone, location,
    package:originalPackage,
    status,
    amount:amountNum,
    discount:discountNum,
    deposit:depositNum,
    balance,
    paymentStatus,
    note,
    shootDate,
    shootTime,
    date:new Date().toLocaleString()
};

vouchers.push(voucher);
saveVouchers(vouchers);
clearForm();
showDashboard();
displayVoucher(voucher);
showVouchers();
refreshCalendar();
}

function setCreateButtonMode(editMode){
    let buttons=document.querySelectorAll('button');
    buttons.forEach(btn=>{
        if(btn.getAttribute('onclick')==='createVoucher()'){
            btn.textContent=editMode ? 'Update Voucher' : 'Voucher ထုတ်ရန်';
        }
    });
}

