function renderDashboardPackagePrices(){
    const st=getAdminSettings();
    let html="";
    Object.entries(st.packages).forEach(([name,price])=>{
        html += "<p><b>"+escapeHtml(name)+"</b> : "+money(price)+"</p>";
    });
    (st.mainPackageOptions||[]).forEach(function(item){ if(item.enabled!==false) html += "<p><b>"+escapeHtml(item.name)+"</b> : "+money(item.price)+"</p>"; });
    html += "<h4>"+escapeHtml(specialPackageName('wedding'))+"</h4>";
    Object.entries(st.weddingPackages).forEach(([name,price])=>{
        html += "<p><b>"+escapeHtml(name)+"</b> : "+money(price)+"</p>";
    });
    html += "<h4>"+escapeHtml(specialPackageName('novitiation'))+"</h4>";
    Object.entries(st.novitiationPackages).forEach(([name,price])=>{
        html += "<p><b>"+escapeHtml(name)+"</b> : "+money(price)+"</p>";
    });
    return html;
}

function toggleDashboardPackagePrices(){
    const box=document.getElementById("dashboardPackagePricesContent");
    if(!box) return;
    const isHidden = box.style.display === "none" || box.style.display === "";
    if(isHidden){
        box.innerHTML = renderDashboardPackagePrices();
        box.style.display = "block";
    }else{
        box.style.display = "none";
    }
}

