function editVoucher(index){
    let vouchers=getVouchers();
    if(!Number.isInteger(index) || !vouchers[index]){
        alert("Voucher မတွေ့ပါ");
        return;
    }

    let v=vouchers[index];
    editingIndex=index;

    document.getElementById("customer").value=v.customer || "";
    document.getElementById("phone").value=v.phone || "";
    document.getElementById("location").value=v.location || "";

    let packageValue=String(v.package || "");
    document.getElementById("weddingPackageBox").style.display="none";
    document.getElementById("NovitiationPackageBox").style.display="none";
    const integratedBox=document.getElementById("packageSubOptionsBox");
    const integratedSelect=document.getElementById("packageSubOption");

    const weddingName=specialPackageName('wedding');
    const novitiationName=specialPackageName('novitiation');
    if(packageValue.includes(weddingName) || packageValue.includes(DEFAULT_ADMIN_SETTINGS.packageNames.wedding)){
        document.getElementById("package").value=weddingName;
        syncIntegratedPackageOption();
        let parts=packageValue.split(" - ");
        if(integratedSelect) integratedSelect.value=parts.slice(1).join(" - ");
        setWeddingPrice();
    } else if(packageValue.includes(novitiationName) || packageValue.includes(DEFAULT_ADMIN_SETTINGS.packageNames.novitiation)){
        document.getElementById("package").value=novitiationName;
        syncIntegratedPackageOption();
        let parts=packageValue.split(" - ");
        if(integratedSelect) integratedSelect.value=parts.slice(1).join(" - ");
        setNovitiationPrice();
    } else {
        document.getElementById("package").value=packageValue;
        if(integratedBox) integratedBox.style.display="none";
        setPackagePrice();
    }

    document.getElementById("status").value=v.status || "";
    document.getElementById("amount").value=v.amount ?? "";
    document.getElementById("discount").value=v.discount ?? 0;
    document.getElementById("deposit").value=v.deposit ?? 0;
    document.getElementById("paymentStatus").value=v.paymentStatus || "";
    document.getElementById("shootDate").value=v.shootDate || "";
    document.getElementById("shootTime").value=v.shootTime || "";
    document.getElementById("note").value=v.note || "";

    setCreateButtonMode(true);
    window.scrollTo({top:0,behavior:'smooth'});
}

function deleteVoucher(index){
    let vouchers=getVouchers();
    if(!Number.isInteger(index) || !vouchers[index]){
        alert("Voucher မတွေ့ပါ");
        return;
    }

    let voucherNo=vouchers[index].number || "ဒီ Voucher";
    let ok=confirm("Voucher ဖျက်မှာ သေချာပါသလား?\n\n"+voucherNo);
    if(!ok) return;

    vouchers.splice(index,1);
    saveVouchers(vouchers);

    if(editingIndex===index) editingIndex=-1;
    else if(editingIndex>index) editingIndex--;

    setCreateButtonMode(false);
    showVouchers();
    showDashboard();
    refreshCalendar();
    alert("Voucher ဖျက်ပြီးပါပြီ");
}

